const {chromium}=require('C:/Temp/openclaw-playwright/node_modules/playwright');
const http=require('http'),fs=require('fs'),path=require('path');
const root=path.resolve('frontend/dist/inquiry-mobile-review');
const server=http.createServer((req,res)=>{let f=path.join(root,decodeURIComponent(req.url.split('?')[0]));if(!fs.existsSync(f)||fs.statSync(f).isDirectory())f=path.join(root,'index.html');res.setHeader('Content-Type',f.endsWith('.js')?'text/javascript':f.endsWith('.css')?'text/css':f.endsWith('.html')?'text/html':'application/octet-stream');res.end(fs.readFileSync(f));});
(async()=>{await new Promise(r=>server.listen(4319,'127.0.0.1',r));const browser=await chromium.launch({channel:'msedge',headless:true});try{const context=await browser.newContext({viewport:{width:390,height:844}});const identity={_id:'visual-user',role:'ADMIN',name:'Preview',lastname:'Admin',first_password_changed:true};const token='test.'+Buffer.from(JSON.stringify({...identity,exp:Math.floor(Date.now()/1000)+3600})).toString('base64url')+'.test';await context.addCookies([{name:'identity',value:JSON.stringify(identity),url:'http://127.0.0.1:4319'},{name:'token',value:token,url:'http://127.0.0.1:4319'}]);const page=await context.newPage();await page.route('**/*',async route=>{const u=new URL(route.request().url());if(u.origin==='http://127.0.0.1:4319'&&!u.pathname.startsWith('/api'))return route.continue();return route.fulfill({json:{success:true,status:'success',data:{docs:[],notifications:[]}}});});await page.goto('http://127.0.0.1:4319/#/home/visual-condo');await page.waitForSelector('app-home');await page.evaluate(()=>{const c=ng.getComponent(document.querySelector('app-home'));c._messageService.clear();c.showComponent('inquiry');ng.applyChanges(c);});await page.waitForSelector('app-inquiry');await page.evaluate(()=>{const c=ng.getComponent(document.querySelector('app-inquiry'));c.inquiries=Array.from({length:12},(_,i)=>({_id:'i'+i,title:'Maintenance request '+(i+1)+' for the main entrance',content:'The entrance light needs attention. Please review the fixture near the main gate.',category:'maintenance',priority:i%2?'medium':'high',status:i%2?'responded':'sent',createdAt:'2026-09-29T12:00:00Z',responses:[]}));c.notices=[{_id:'n1',title:'Scheduled maintenance for the water supply this weekend',content:'Water service will be interrupted while the maintenance team completes repairs.',type:'maintenance',priority:'high',createdAt:'2026-09-29T12:00:00Z',isRead:false,attachments:[]}];c.messageService.clear();c.loadingInquiries=false;c.loadingNotices=false;ng.applyChanges(c);});await page.locator('app-inquiry').scrollIntoViewIfNeeded();for(const width of [320,390,768,1280]){await page.setViewportSize({width,height:900});await page.locator('app-inquiry').scrollIntoViewIfNeeded();await page.screenshot({path:path.join(root,'inquiries-'+width+'.png')});console.log(JSON.stringify(await page.evaluate(()=>({width:innerWidth,viewportOverflow:document.documentElement.scrollWidth>innerWidth,statsHeight:document.querySelector('.inquiry-stats').getBoundingClientRect().height,mobileDisplay:getComputedStyle(document.querySelector('.inquiry-mobile-list')).display,cards:document.querySelectorAll('.inquiry-record-card').length}))))};await page.setViewportSize({width:390,height:900});await page.locator('.inquiry-mobile-list p-paginator .p-paginator-next').click();console.log('PAGE2',await page.locator('.inquiry-record-card').count());await page.getByRole('tab',{name:'Notices',exact:true}).click();await page.locator('app-inquiry').screenshot({path:path.join(root,'notices-390.png')});console.log('NOTICES',await page.locator('.notice-card').count());}finally{await browser.close();server.close();}})().catch(e=>{console.error(e);server.close();process.exitCode=1});
